drop function if exists public.admin_website_ids(text, text);
create or replace function public.admin_website_ids( p_search text default null, p_status text default null, p_limit integer default 1000, p_offset integer default 0 ) returns table (id uuid) language sql stable security definer set search_path = public as $$ select w.id from public.websites w left join public.categories c on c.id = w.primary_category_id where (p_status is null or p_status = 'all' or w.status::text = p_status) and ( coalesce(btrim(p_search), '') = '' or position( lower(btrim(p_search)) in lower(w.domain || ' ' || coalesce(w.title, '') || ' ' || coalesce(c.slug, '')) ) > 0 ) order by w.updated_at desc, w.id asc limit greatest(1, least(coalesce(p_limit, 1000), 1000)) offset greatest(0, coalesce(p_offset, 0)); $$;
comment on function public.admin_website_ids(text, text, integer, integer) is 'One window of the listing ids an admin filter matches, for the header checkbox that selects a whole filter rather than a page. Ids only, and the caller walks it to the end - PostgREST caps a single response and does not say so.';
create or replace function public.admin_website_domains(p_ids uuid[]) returns table (id uuid, domain text) language sql stable security definer set search_path = public as $$ select w.id, w.domain from public.websites w where w.id = any(coalesce(p_ids, '{}'::uuid[])) order by w.updated_at desc, w.id asc; $$;
comment on function public.admin_website_domains(uuid[]) is 'The domains behind a selection of listing ids. Domains only - no costs, no contacts, nothing an admin row carries that a paste box has no business holding.';
